insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id) values ('che-ek-215', 'chemistry-electrochemistry-and-chemical-kinetics', 'chemistry', 'Two runs at the same [B]: [A] = 0.10 M gives rate $1.2 \times 10^{-4}$; [A] = 0.20 M gives rate $4.8 \times 10^{-4}$. Order in A and the factor by which rate changes if both [A] and [B] are doubled (order in B is 1) are', '["2 and a factor of 8","1 and a factor of 4","2 and a factor of 4","0 and a factor of 2"]'::jsonb, 0, 'Rate ×4 when [A] ×2 ⇒ order 2 in A. Overall rate $= k[\mathrm{A}]^2[\mathrm{B}]$, so doubling both species multiplies the rate by $4 \times 2 = 8$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb, 'hard', 'rate-law') on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source, difficulty = excluded.difficulty, concept_id = excluded.concept_id;
